import pandas as pd

def get_band(val):
    if val < 60:
        return '<60'
    elif val < 75:
        return '60-75'
    else:
        return '>=75'

df['습도 구간'] = df['외기습도 (%)'].apply(get_band)
# Ensure category order for legend/grouping consistency
cat_order = ['<60', '60-75', '>=75']
df['습도 구간'] = pd.Categorical(df['습도 구간'], categories=cat_order, ordered=True)
